#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."

# Auto-generated same-scale G0 calibration job.
# This job is intentionally separate from nonlinear G1 KD/deep-chain stress tests.
BASE=${BASE:-'Qwen/Qwen3-4B-Base'}
ENCODER=${ENCODER:-'sentence-transformers/all-mpnet-base-v2'}
SAMPLES=${SAMPLES:-4}
TEMPERATURE=${TEMPERATURE:-0.7}
TOP_P=${TOP_P:-0.95}
BANK=${BANK:-'runs/banks/s47/response_bank.estimate.npz'}
SELECTED=${SELECTED:-'runs/banks/s47/selected_probes.json'}
PROBES=${PROBES:-'data/probes/interventions.jsonl'}
mkdir -p runs/calibration/s47/adapters runs/calibration/s47/responses runs/calibration/s47/prepared runs/calibration/s47/scores
python scripts/subset_probe_pool.py --probes "$PROBES" --selected "$SELECTED" --output runs/calibration/s47/selected_probes.jsonl

# Build all bank-complete lightweight descendants in one base-model loading session.
python scripts/build_weighted_lora_adapters.py \
  --base "$BASE" \
  --plan 'runs/calibration/plan_v09/cal_support_plan.csv' 'runs/calibration/plan_v09/cal_open_candidates.csv' \
  --adapter Math=runs/experts/s47/math/adapter \
  --adapter Code=runs/experts/s47/code/adapter \
  --adapter Medical=runs/experts/s47/medical/adapter \
  --adapter Science=runs/experts/s47/science/adapter \
  --output-dir runs/calibration/s47/adapters

# One independent anchor realization per target seed is generated below; paired seeds reduce variance.
echo '=== csig_000 signal ==='
python scripts/run_text_probe_bank.py --model "$BASE" --probes runs/calibration/s47/selected_probes.jsonl --encoder "$ENCODER" --samples "$SAMPLES" --seed 129928751 --temperature "$TEMPERATURE" --top-p "$TOP_P" --paired-seeds --output 'runs/calibration/s47/responses/csig_000.target.npz'
python scripts/run_text_probe_bank.py --model "$BASE" --probes runs/calibration/s47/selected_probes.jsonl --encoder "$ENCODER" --samples "$SAMPLES" --seed 139928770 --temperature "$TEMPERATURE" --top-p "$TOP_P" --paired-seeds --output 'runs/calibration/s47/responses/csig_000.anchor.npz'
python scripts/prepare_target_decomposition.py --bank "$BANK" --base 'runs/calibration/s47/responses/csig_000.anchor.npz' --target 'runs/calibration/s47/responses/csig_000.target.npz' --selected "$SELECTED" --target-selected-only --output 'runs/calibration/s47/prepared/csig_000.npz'
echo '=== csig_001 signal ==='
python scripts/run_text_probe_bank.py --model "$BASE" --load-in-8bit --probes runs/calibration/s47/selected_probes.jsonl --encoder "$ENCODER" --samples "$SAMPLES" --seed 1672909720 --temperature "$TEMPERATURE" --top-p "$TOP_P" --paired-seeds --output 'runs/calibration/s47/responses/csig_001.target.npz'
